import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Monitoring and event feed","description":"","frontmatter":{"pageId":"admins/monitoring","contentRevision":1},"headers":[],"relativePath":"en/admins/monitoring.md","filePath":"en/admins/monitoring.md"}'),s={name:"en/admins/monitoring.md"};function o(r,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="monitoring-and-event-feed" tabindex="-1">Monitoring and event feed <a class="header-anchor" href="#monitoring-and-event-feed" aria-label="Permalink to &quot;Monitoring and event feed&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>GET /health checks process availability; /metrics exposes metrics. Restrict network access and collect from a trusted host. Administrative /status returns operational state; /actions correlates changes with operators.</p><p>SSE GET /api/admin/events uses epoch:seq identifiers. Send Last-Event-ID on reconnect. A gap means restart/buffer overflow lost events: reread current state instead of deriving it from an incomplete feed. Defaults are 1000 buffered events and a ping every 15 seconds.</p><p>Monitor free disk space, the age of the last successful backup, login/save/delivery refusals and long live sessions. “Process alive” does not replace colony read/write verification.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The feed intentionally excludes private chat, wallets, parcels and raids not yet landed. Keep tokens/full saves out of metrics and shared logs. /metrics is application-public: restrict it at the network layer.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./discord">Discord bot</a></li><li><a href="./troubleshooting">Administrator troubleshooting</a></li><li><a href="./api">REST API reference</a></li></ul>',10)])])}const h=a(s,[["render",o]]);export{m as __pageData,h as default};
